# Let's solve this with a simple backtracking/greedy approach
# We need to partition {1,...,20} into 3 subsets each summing to 70

def solve_partition():
    numbers = list(range(1, 21))
    target = 70
    assignment = [None] * 20
    sums = [0, 0, 0]

    def backtrack(idx):
        if idx == 20:
            return all(s == target for s in sums)

        num = numbers[idx]
        for subset in range(3):
            if sums[subset] + num <= target:
                sums[subset] += num
                assignment[idx] = subset
                if backtrack(idx + 1):
                    return True
                sums[subset] -= num
                assignment[idx] = None
        return False

    # Sort in descending order for better pruning
    numbers_sorted = sorted(numbers, reverse=True)

    def backtrack2(idx):
        if idx == 20:
            return all(s == target for s in sums)

        num = numbers_sorted[idx]
        seen = set()
        for subset in range(3):
            if sums[subset] not in seen and sums[subset] + num <= target:
                seen.add(sums[subset])
                sums[subset] += num
                assignment[idx] = subset
                if backtrack2(idx + 1):
                    return True
                sums[subset] -= num
                assignment[idx] = None
        return False

    if backtrack2(0):
        # Map back to original indices
        result = [None] * 20
        for idx, num in enumerate(numbers_sorted):
            result[num - 1] = assignment[idx]
        return result
    return None

result = solve_partition()
if result:
    print("Solution found!")
    print("Assignment (0-indexed):", result)

    # Verify
    subsets = [[], [], []]
    for i, s in enumerate(result):
        subsets[s].append(i + 1)

    for i, sub in enumerate(subsets):
        print(f"Subset {i}: {sub}, sum = {sum(sub)}")
else:
    print("No solution found")
